diff --git a/app/src/worker/queue/processHandler.js b/app/src/worker/queue/processHandler.js
index 0000000..0000000 100644
--- a/app/src/worker/queue/processHandler.js
+++ b/app/src/worker/queue/processHandler.js
@@ -1,17 +1,17 @@
 import render from '../renderers/chrome'

 // isJobExpired :: (Configuration, Job) -> Boolean
 const isJobExpired = (configuration, job) =>
   Date.now() - job.data.queuedAt > configuration.queue.job.stale_timeout

 // queueProcessHandler :: (Configuration, Logger, ScriptProvider) -> Function
 export default (configuration, logger, scriptProvider) => async job => {
   if (isJobExpired(configuration, job)) {
     throw new Error(`Job "${job.id}" with url "${job.data.url}" timed out."`)
   }

   logger.debug(`Processing job "${job.id}" with url "${job.data.url}".`)

   return await render(configuration, logger, scriptProvider)(job.data.url)
 }

diff --git a/app/src/manager/queue/jobCompletedHandler.js b/app/src/manager/queue/jobCompletedHandler.js
index 0000000..0000000 100644
--- a/app/src/manager/queue/jobCompletedHandler.js
+++ b/app/src/manager/queue/jobCompletedHandler.js
@@ -1,18 +1,18 @@
 import { juxt, when } from 'ramda'
 import { resolveJobDuration } from './utils'

 // jobCompletedHandler :: (Logger, Queue, RequestRegistry) -> Function
 export default (logger, queue, requestRegistry) => (jobId, result) => when(
   jobId => requestRegistry.has(jobId),
   juxt([
     jobId => requestRegistry.complete(jobId, JSON.parse(result)),
     async jobId => {
       const job = await queue.getJob(jobId)

       logger.info(`${jobId} ${job.data.url} 200 ${resolveJobDuration(job)}`)

       job.remove()
     },
   ]),
 )(jobId)

